rong>MAID’S ROOM: 1</strong></li><li><strong>Special Features</strong></li></ul><p>- Gated community w/ 24 hrs. security plus surveillance camera</p><p>- 300+ sq.m. of open space</p><p>- All Master’s bedroom has its own walk-in closet and toilet & bath</p><p>-<strong> Park-like podium walkway to the main entrance for the houses</strong></p><p>- 7.2 meter wide driveway</p><p>- Individual parking spaces</p><p>- Individual viewing decks</p><p><br></p>','{"barangay":"","municiplaity":"San Juan City","province":"","region":"","street":"Bonifacio st ","village":""}','13150000','2630000.00','{"option_money_duration":"","payment_mode":"","tax_allocation":"","bank_loan":false,"pagibig_loan":false,"assume_balance":false}','143','27','3','3','1','https://images.philproperties.ph/global_assets/images/properties/73262625363045012953166628283010969225019346188565_33eca276078dd1bad9337e27270e80d2.jpg','[]','[]','{"authority_type":"Non-Exclusive Authority To Sell","authority_to_sell_expiration":0,"owned_by":"Onofre","contact_details":"09321876596","exact_address":"Bonifacio st. San Juan"}','1447685170','1660599695','1','0','0','[]'),
